        right_pre = build(root_idx + 1, in_right, post_left + left_size, post_right - 1)
        return root + left_pre + right_pre

    return build(0, len(inorder) - 1, 0, len(postorder) - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals and
    returns the preorder traversal as a string.
    """
    if not inorder or not postorder:
        return ''

    index_map = {ch: i for i, ch in enumerate(inorder)}

    def build(i_start, i_end, p_start, p_end):
        if i_start > i_end:
            return ''
        if i_start == i_end:
            return inorder[i_start]
        root = postorder[p_end]
        root_idx = index_map[root]
        left_size = root_idx - i_start
        left_pre = build(i_start, root_idx - 1, p_start, p_start + left_size - 1)
        right_pre = build(root_idx + 1, i_end, p_start + left_size, p_end - 1)
        return root + left_pre + right_pre

    return build(0, len(inorder) - 1, 0, len(postorder) - 1)

def preorder_traversal(inorder: str, postorder: str) -> str:
    idx_map = {c: i for i, c in enumerate(inorder)}
    n = len(postorder)
    post_idx = n - 1

    def helper(l: int, r: int) -> str:
        nonlocal post_idx
        if l > r:
            return ''
        root = postorder[post_idx]
        post_idx -= 1
        i = idx_map[root]
        left = helper(l, i - 1)
        right = helper(i + 1, r)
        return root + left + right

    return helper(0, len(inorder) - 1)

